    X.unitKey = (t, unit) => { const d = new Date(t), y = d.getFullYear(), m = d.getMonth() + 1; return unit === 'year' ? y + '' : unit === 'season' ? y + '-Q' + Math.ceil(m / 3) : unit === 'half' ? y + '-' + p2(m) + (d.getDate() <= 15 ? '上' : '下') : y + '-' + p2(m); };
