try { new Function('X', 'applyMacros', "/* 🫂 抱抱：不开心的时候点一下——TA 给你一个长长的抱抱，陪你慢慢呼吸（TA 的声音数着节拍），给你写几句话，再陪你做几件让自己好一点的小事 */\nif (window.__gyxHug) return; window.__gyxHug = 1;\nX.feat('gyxHug', { n: '🫂 抱抱', desc: '不开心时点一下，TA 抱抱你、陪你呼吸、陪你缓一缓' });\nconst S = X.store('hug');\nlet D = { log: [], cfg: { voice: true } };\nconst SMALL = ['去倒一杯温水，慢慢喝完', '把窗户打开一条缝，吹一会儿风', '洗把脸，或者洗个热水澡', '给自己换一件舒服的衣服', '吃一点甜的东西', '把手机放下五分钟，闭上眼睛', '听一首你喜欢的歌', '抱着枕头躺一会儿', '写下三件今天还不错的小事', '出门走一小圈'];\nlet BR = null;\nasync function note(c, why) {\n    if (X.bailu()) return X.cards(['安慰', '抱抱', '聊天'], c, 3).join('\\n') || '我在。不用急着好起来，先让我抱一会儿。';\n    return X.plain(await X.ask(`${X.who(c)}\\n她现在不太好${why ? '，她说：「' + why + '」' : '（她没说为什么）'}。给她写几句话：先接住她的情绪（不说教、不急着讲道理、不说「别难过」），告诉她你在，然后温柔地陪着。60~150 字，像你本人在她耳边说。只输出这段话。`) || '我在。不用急着好起来，先让我抱一会儿。');\n}\nwindow.gyxHugOpen = async function (why) {\n    const c = X.cur(); if (!c) return;\n    const ov = document.createElement('div'); ov.id = 'gyxHugOv';\n    let av = ''; try { av = getAvatarHTML(c, 96); } catch (e) {}\n    ov.innerHTML = `<div class=\"hg-x\" onclick=\"gyxHugClose()\">✕</div><div class=\"hg-c\"><div class=\"hg-arms\"><div class=\"hg-av\">${av}</div><i class=\"l\"></i><i class=\"r\"></i></div><div class=\"hg-t\">${X.esc(X.name(c))} 抱住了你</div>\n        <div class=\"hg-why\"><input id=\"gyxHugWhy\" class=\"gyx-in\" placeholder=\"想说说怎么了吗？（不说也可以）\" value=\"${X.esc(why || '')}\"><button class=\"gyx-btn lite\" onclick=\"gyxHugNote()\">说给 TA</button></div>\n        <div class=\"hg-note gyx-hand\" id=\"gyxHugNote\">……</div>\n        <div class=\"hg-br\"><div class=\"hg-ball\" id=\"gyxHugBall\"></div><b id=\"gyxHugBT\">跟着圆圈呼吸</b><button class=\"gyx-btn lite\" onclick=\"gyxHugBreath()\">开始（吸 4 · 停 4 · 呼 6）</button></div>\n        <div class=\"hg-small\"><div class=\"gyx-tip\">然后，陪你做一件小事：</div>${X.pick([SMALL.slice(0, 5), SMALL.slice(5)]).map(s => `<label><input type=\"checkbox\" onchange=\"this.parentElement.classList.toggle('ok',this.checked)\"> ${s}</label>`).join('')}</div>\n        <div class=\"gyx-tip hg-foot\">如果真的很难受、撑不住，也要记得找身边信任的人，或者专业的心理热线聊一聊。你值得被好好照顾。</div></div>`;\n    document.body.appendChild(ov);\n    D.log.unshift({ at: Date.now(), cid: String(c.id), why: why || '' }); D.log = D.log.slice(0, 100); await S.set('d', D);\n    window.gyxHugNote();\n};\nwindow.gyxHugNote = async function () {\n    const c = X.cur(), why = ((document.getElementById('gyxHugWhy') || {}).value || '').trim(), el = document.getElementById('gyxHugNote'); if (!el) return;\n    el.textContent = '……'; const t = await note(c, why); el.textContent = t; if (D.cfg.voice) X.speak(c, t);\n    if (why) { const L = D.log[0]; if (L) { L.why = why; S.set('d', D); } X.reach(c, `她刚刚不太好，点了「抱抱」，跟你说：「${why}」。你已经抱着她、跟她说了几句了，现在在聊天里继续陪着她（温柔、别说教）`); }\n    return t;\n};\nwindow.gyxHugBreath = function () {\n    if (BR) { clearTimeout(BR.t); BR = null; }\n    const ball = document.getElementById('gyxHugBall'), tx = document.getElementById('gyxHugBT'), c = X.cur(); if (!ball) return;\n    const steps = [['吸气', 4000, 1.6], ['停一下', 4000, 1.6], ['慢慢呼气', 6000, 1]]; let i = 0, round = 0; BR = {};\n    const go = () => { if (!BR || !document.getElementById('gyxHugBall')) return; const [w, ms, sc] = steps[i]; tx.textContent = w + (round ? `（第 ${round + 1} 轮）` : ''); ball.style.transition = `transform ${ms}ms ease-in-out`; ball.style.transform = `scale(${sc})`; if (D.cfg.voice && round < 2) X.speak(c, w); i++; if (i >= steps.length) { i = 0; round++; } if (round >= 5) { tx.textContent = '好一点了吗？'; BR = null; return; } BR.t = setTimeout(go, ms); };\n    go();\n};\nwindow.gyxHugClose = () => { if (BR) { clearTimeout(BR.t); BR = null; } X.stopSpeak(); const o = document.getElementById('gyxHugOv'); if (o) o.remove(); };\nwindow.gyxHugData = () => D;\n// 聊天栏放一颗 🫂\nfunction btn() { const row = document.getElementById('chatToolIconsRow'); if (!row || document.getElementById('gyxHugBtn')) return; if (!X.on('gyxHug')) return; const b = document.createElement('button'); b.className = 'btn-edit-small'; b.id = 'gyxHugBtn'; b.title = '抱抱'; b.textContent = '🫂'; b.onclick = () => window.gyxHugOpen(); row.appendChild(b); }\naddEventListener('gyx:feat', e => { if (e.detail && e.detail.id === 'gyxHug' && !e.detail.on) { const b = document.getElementById('gyxHugBtn'); if (b) b.remove(); } });\nX.action({ key: 'gyx_hug', label: '她好像不太开心，给她一个抱抱', hint: '她最近情绪低落', need: c => { try { const d = window.gyMoodData && window.gyMoodData().days[X.day()]; return !!(d && d.me && ['累', '委屈', '烦', 'emo', '想你'].includes(d.me.m)); } catch (e) { return false; } }, run: async c => (await X.reach(c, '你感觉她今天不太开心，想给她一个抱抱，陪她缓一缓（可以提醒她聊天栏有个 🫂）')) ? '给了你一个抱抱' : null }, 'gyxHug');\nX.ctx(() => { const L = D.log[0]; return L && Date.now() - L.at < 6 * 3600000 ? `【她刚才不太好】她几个小时前点了「抱抱」${L.why ? '，说：「' + L.why + '」' : ''}。聊天时温柔一点，多陪着她。` : ''; }, 'gyxHug');\nX.today(() => { const L = D.log.filter(x => X.day(new Date(x.at)) === X.day()); return { title: '🫂 抱抱', rows: L.length ? [{ t: L.length + ' 次', x: '今天被抱了抱', go: 'gyxHugOpen()' }] : [] }; }, 'gyxHug');\nX.css('gyxHgCss', `#gyxHugOv{position:fixed;inset:0;z-index:100007;background:linear-gradient(170deg,#fde2e4,#e2ece9 60%,#dfe7fd);display:flex;justify-content:center;overflow:auto;animation:hgIn .6s both}@keyframes hgIn{from{opacity:0}}\n.hg-x{position:fixed;right:18px;top:14px;font-size:20px;color:#999;cursor:pointer;z-index:2}.hg-c{width:min(440px,92vw);padding:40px 0 30px;display:flex;flex-direction:column;align-items:center;gap:14px;color:#4a3b40}\n.hg-arms{position:relative;width:200px;height:150px;display:flex;justify-content:center;align-items:center}.hg-av{animation:hgB 3s ease-in-out infinite}.hg-arms i{position:absolute;top:60px;width:90px;height:34px;border-radius:20px;background:#ffd7c4;box-shadow:0 4px 10px rgba(0,0,0,.08)}.hg-arms i.l{left:-10px;transform:rotate(20deg);animation:hgL 1.2s .3s both}.hg-arms i.r{right:-10px;transform:rotate(-20deg);animation:hgR 1.2s .3s both}\n@keyframes hgL{from{transform:translateX(-60px) rotate(40deg);opacity:0}to{transform:translateX(30px) rotate(10deg);opacity:1}}@keyframes hgR{from{transform:translateX(60px) rotate(-40deg);opacity:0}to{transform:translateX(-30px) rotate(-10deg);opacity:1}}@keyframes hgB{50%{transform:scale(1.04)}}\n.hg-t{font-size:18px}.hg-why{display:flex;gap:8px;width:100%}.hg-note{font-size:20px;line-height:1.9;padding:16px 18px;border-radius:18px;background:rgba(255,255,255,.7);width:100%;box-sizing:border-box;min-height:80px}\n.hg-br{display:flex;flex-direction:column;align-items:center;gap:10px;padding:14px;border-radius:18px;background:rgba(255,255,255,.5);width:100%;box-sizing:border-box}.hg-ball{width:70px;height:70px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#fff,#b8d8f8);box-shadow:0 0 30px rgba(150,190,240,.6);margin:20px}\n.hg-small{width:100%}.hg-small label{display:block;padding:8px 10px;border-radius:12px;background:rgba(255,255,255,.55);margin:5px 0;font-size:14px;cursor:pointer}.hg-small label.ok{text-decoration:line-through;opacity:.6}.hg-foot{text-align:center;font-size:12px}`);\nX.mini({ id: 'gyxHug', icon: '🫂', title: '抱抱', desc: '不开心时点一下：TA 抱抱你、陪你呼吸、给你写几句话', onOpen: () => window.gyxHugOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.log = D.log || []; D.cfg = Object.assign({ voice: true }, D.cfg || {}); btn(); setInterval(btn, 3000); })();\nX.widget('gyxHugW', { n: '抱抱', sizes: ['s'], tap: () => window.gyxHugOpen(), r: w => X.gw(w, '🫂', '抱抱', [X.v('要抱抱吗', '我在', '过来抱一下')]) }, 'gyxHug');\nX.memArr({ k: 'gyxHug', ico: '🫂', n: '不开心的时候', d: '你点「抱抱」时说的话（TA 会记着多陪你）', arr: () => D.log, text: x => x.why || '（没说为什么）', field: 'why', save: () => S.set('d', D) }, 'gyxHug');\n\n//# sourceURL=gyx-plugin/抱抱.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🫂 抱抱 出错：', e); }
/* ==== 🥺 轮到你哄TA ==== */
try { new Function('X', 'applyMacros', "/* 🥺 轮到你哄TA：TA 也会有倒霉的一天——被老板骂了、东西丢了、莫名其妙就是不开心。这次换你哄 TA：你在聊天里说的每句话都会让 TA 的心情条慢慢回来（敷衍的话不算），哄好了 TA 会记着你的好 */\nif (window.__gyxCoax) return; window.__gyxCoax = 1;\nX.feat('gyxCoax', { n: '🥺 轮到你哄TA', desc: 'TA 也会低落，换你来哄，心情条跟着你的话慢慢回来' });\nconst S = X.store('coax');\nlet D = { on: {}, log: [], cfg: { per: 4 } };   // on[cid] = {why, mood(0~100), at, seen, steps:[{t, d, at}]}; log = [{cid, why, at, end, n, thanks}]\nconst WHY = ['今天被领导当众说了一顿', '出门忘带伞，淋成了落汤鸡', '最喜欢的杯子摔碎了', '排了一小时队，轮到自己卖完了', '熬夜做的东西被说不行', '莫名其妙就是不开心', '和朋友闹了点别扭', '感冒了，头好晕', '手机摔了，屏幕裂了', '梦到你不理我了，醒来还难受', '加班到很晚，饭都没吃', '被人误会了又解释不清'];\nconst H = cid => ((typeof globalChats !== 'undefined' && globalChats[cid]) || []).filter(m => m && m.sender !== 'system' && !m.side);\nconst GOOD = [[/抱抱|抱一下|抱紧|抱你/, 18], [/亲亲|亲一下|么么|mua/i, 14], [/心疼|辛苦了|委屈你了|难为你了/, 20], [/我在|陪着你|有我|我陪你/, 18], [/爱你|喜欢你|最喜欢/, 15], [/不哭|乖|摸摸|揉揉/, 12], [/没关系|不是你的错|你已经很棒|你很棒|做得很好/, 22], [/请你|给你买|带你去|奶茶|好吃的|甜品/, 14], [/讲讲|怎么了|发生什么|跟我说/, 10], [/[🥺🤗😘❤️💕🫶]/u, 6]];\nconst BAD = /^(哦|嗯|好吧|行吧|随便|然后呢|哦哦|知道了|那又怎样)$/;\nasync function score(c, st, text) {\n    const t = X.plain(text); if (!t) return 0;\n    if (!X.bailu()) { const j = X.json(await X.ask(`${X.who(c)}\\n你今天很低落（${st.why}），现在心情 ${st.mood}/100。她刚对你说：「${t}」\\n这句话能让你好受多少？真诚、具体、懂你的话加得多；敷衍、讲道理、说教的不加甚至减。\\n只输出 JSON：{\"d\":-10到30的整数}`)); if (j && isFinite(+j.d)) return Math.max(-10, Math.min(30, Math.round(+j.d))); }\n    if (BAD.test(t)) return -5; let d = 2; GOOD.forEach(([re, v]) => { if (re.test(t)) d += v; }); if (t.length > 20) d += 4; return Math.min(30, d);\n}\nasync function start(c, why) {\n    const cid = String(c.id); if (D.on[cid]) return D.on[cid];\n    let r = why; if (!r && !X.bailu()) r = X.plain(await X.ask(`${X.who(c)}\\n今天你遇到了一件倒霉 / 难过的事。按你的身份和生活想一件具体的（一句话，20 字以内，别太严重）。只输出这件事。`) || '');\n    r = (r || X.pick(WHY)).slice(0, 40);\n    D.on[cid] = { why: r, mood: 15 + Math.floor(Math.random() * 20), at: Date.now(), seen: H(cid).length, steps: [] }; await S.set('d', D); return D.on[cid];\n}\nasync function done(c, st) {\n    const cid = String(c.id); delete D.on[cid];\n    let t = X.bailu() ? null : await X.ask(`${X.who(c)}\\n你今天因为「${st.why}」很低落，她哄了你 ${st.steps.length} 句，你现在好了。真心谢谢她，说一两句（可以有点不好意思）。`);\n    t = X.plain(t || X.pick(X.cards(['情话', '撒娇'], c, 2).concat(['……好了，被你哄好了。谢谢你，真的。', '有你在，好像什么都没那么糟了。', '哼，看在你这么努力的份上，原谅这个世界了。'])));\n    D.log.unshift({ cid, why: st.why, at: st.at, end: Date.now(), n: st.steps.length, thanks: t }); await S.set('d', D);\n    X.say(c, t); X.notify(c, `🥺 ${X.esc(X.name(c))} ${X.v('被你哄好了', '心情回来了', '不难过了')}`, st.why, () => window.gyxCoaxOpen(cid));\n}\nlet BUSY = null;\nfunction watch() { if (BUSY) return BUSY; BUSY = watch0().finally(() => { BUSY = null; }); return BUSY; }\nasync function watch0() {\n    if (!X.on('gyxCoax')) return;\n    for (const cid of Object.keys(D.on)) {\n        const st = D.on[cid], c = X.char(cid); if (!c) { delete D.on[cid]; continue; } const L = H(cid); if (L.length <= st.seen) { st.seen = L.length; continue; }\n        const fresh = L.slice(st.seen).filter(m => m.sender === 'me'); st.seen = L.length;\n        for (const m of fresh) { const d = await score(c, st, m.text); st.mood = Math.max(0, Math.min(100, st.mood + d)); st.steps.push({ t: X.plain(m.text).slice(0, 60), d, at: Date.now() }); }\n        await S.set('d', D); if (document.getElementById('gyxCoaxOv')) window.gyxCoaxOpen(cid);\n        if (st.mood >= 100) await done(c, st);\n    }\n}\nwindow.gyxCoaxStart = async (cid, why) => { const c = X.char(cid) || X.cur(); if (!c) return null; const st = await start(c, why); if (!X.bailu()) await X.reach(c, `你今天很低落：${st.why}。来找她，但别直说「快哄我」——可以闷闷的、可以嘴硬说没事，让她察觉到`); else X.say(c, X.pick(['……今天好倒霉。', '没事。就是有点累。', '唉。', `${st.why}……算了不说了。`])); window.gyxCoaxOpen(c.id); return st; };\nwindow.gyxCoaxSay = async cid => { const inp = document.getElementById('gyxCoaxIn'), t = (inp && inp.value || '').trim(); if (!t) return; inp.value = ''; const sid = String(cid); globalChats[sid] = globalChats[sid] || []; globalChats[sid].push({ sender: 'me', text: t, timestamp: Date.now(), readBy: [] }); try { saveAllData(); if (typeof renderChatMessages === 'function' && String(currentChatSessionId) === sid) renderChatMessages(); } catch (e) {} await watch(); await watch(); const st = D.on[sid], c = X.char(sid); if (st && c) { const r = X.bailu() ? X.pick(st.mood > 60 ? ['……嗯。好一点了。', '你再说一句。', '哼，继续。'] : ['嗯……', '还是有点难受。', '你抱抱我好不好。', '……']) : X.plain(await X.ask(`${X.who(c)}\\n你今天很低落（${st.why}），心情 ${st.mood}/100，她在哄你，刚说：「${t}」。按现在的心情回一句（心情越高越软）。`) || '嗯……'); X.say(c, r); } };\nwindow.gyxCoaxData = () => D;\nwindow.gyxCoaxOpen = function (who) {\n    const c = X.char(who) || X.cur(); if (!c) return; const cid = String(c.id), st = D.on[cid], L = D.log.filter(x => x.cid === cid);\n    X.panel('gyxCoaxOv', '🥺 轮到你哄 TA', `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxCoaxOpen')}</div>\n        ${st ? `<div class=\"gyx-card\"><b>${X.esc(X.name(c))} 今天不开心</b><div class=\"gyx-tip\">${X.esc(st.why)}</div><div class=\"cx-bar\"><i style=\"width:${st.mood}%\"></i><span>${st.mood}/100</span></div>\n            <div class=\"gyx-tip\">${st.mood < 30 ? X.v('还很低落……', '闷闷的，不太想说话', '眼眶还红着') : st.mood < 70 ? X.v('好一点了，再哄哄', '嘴角松动了一点', '开始愿意说话了') : X.v('快好了！', '已经在偷偷笑了', '就差一句了')}</div>\n            ${st.steps.slice(-6).reverse().map(x => `<div class=\"cx-st\"><span>${X.esc(x.t)}</span><b class=\"${x.d > 0 ? 'up' : 'dn'}\">${x.d > 0 ? '+' : ''}${x.d}</b></div>`).join('')}\n            <div class=\"gyx-row\"><input id=\"gyxCoaxIn\" class=\"gyx-in\" style=\"flex:1\" placeholder=\"哄哄 TA…（在聊天里说也算）\" onkeydown=\"if(event.key==='Enter')gyxCoaxSay('${cid}')\"><button class=\"gyx-btn\" onclick=\"gyxCoaxSay('${cid}')\">说</button></div></div>`\n        : `<div class=\"gyx-tip\">${X.v('TA 现在挺好的。', '今天 TA 心情还不错。', '暂时不用哄～')}TA 有时候会自己低落，你也可以问问 TA 今天怎么了。</div><button class=\"gyx-btn lite\" onclick=\"this.disabled=true;gyxCoaxStart('${cid}')\">TA 今天好像不太开心？</button>`}\n        <div style=\"font-weight:700;margin:12px 0 4px\">哄好过的</div>${L.slice(0, 15).map(x => `<div class=\"gyx-card\"><div class=\"gyx-tip\">${new Date(x.at).toLocaleDateString()} · ${X.esc(x.why)} · 哄了 ${x.n} 句</div>${X.esc(x.thanks)}</div>`).join('') || '<div class=\"gyx-tip\">还没哄过</div>'}`);\n};\nX.ctx(id => { const st = D.on[String(id)]; if (st) return `【你今天很低落】因为：${st.why}。现在心情 ${st.mood}/100（越低越难受）。她在哄你——按这个心情说话：低的时候闷闷的、简短，慢慢被她哄软；敷衍的话不领情。`; const x = D.log.find(l => l.cid === String(id)); return x && Date.now() - x.end < 2 * 864e5 ? `【前阵子你因为「${x.why}」低落，她把你哄好了】你记得她的好。` : ''; }, 'gyxCoax');\nX.action({ key: 'gyx_coax', label: '今天有点低落，想让她哄哄', hint: 'TA 也会有倒霉的一天', need: c => !D.on[String(c.id)] && !D.log.some(x => x.cid === String(c.id) && Date.now() - x.end < (+D.cfg.per || 4) * 864e5),\n    run: async c => { const st = await start(c, ''); return (await X.reach(c, `你今天很低落：${st.why}。来找她，闷闷的，别直接说「哄我」`)) ? '今天有点低落' : null; } }, 'gyxCoax');\nX.today(() => ({ title: '🥺 哄 TA', rows: Object.keys(D.on).map(cid => ({ t: D.on[cid].mood + '/100', x: X.esc(X.name(X.char(cid))) + ' 不开心：' + X.esc(D.on[cid].why.slice(0, 14)), go: `gyxCoaxOpen('${cid}')` })).concat(D.log.filter(x => X.day(new Date(x.end)) === X.day()).map(x => ({ t: '哄好了', x: X.esc(X.name(X.char(x.cid))), go: `gyxCoaxOpen('${x.cid}')` }))) }), 'gyxCoax');\nX.widget('gyxCoaxW', { n: '哄 TA', sizes: ['s', 'm'], tap: () => window.gyxCoaxOpen(), r: w => { const c = X.cur(), st = c && D.on[String(c.id)]; return X.gw(w, st ? '🥺' : '😊', st ? X.name(c) + ' 不开心' : '哄 TA', st ? ['心情 ' + st.mood + '/100', X.esc(st.why)] : ['哄好过 ' + D.log.length + ' 次']); } }, 'gyxCoax');\nX.memArr({ k: 'gyxCoax', ico: '🥺', n: '哄 TA', d: 'TA 低落过的事、你哄好 TA 后 TA 说的话', arr: () => D.log, text: x => x.why + '｜' + x.thanks, edit: (x, v) => { const [a, b] = v.split('｜'); x.why = a; if (b != null) x.thanks = b; }, meta: x => new Date(x.at).toLocaleDateString() + ' · 哄了 ' + x.n + ' 句', save: () => S.set('d', D) }, 'gyxCoax');\nX.css('gyxCoaxCss', `.cx-bar{position:relative;height:16px;border-radius:10px;background:#eee;overflow:hidden;margin:10px 0 4px}.cx-bar i{display:block;height:100%;background:linear-gradient(90deg,#9db4ff,#ff9ac1);transition:width .6s}.cx-bar span{position:absolute;right:8px;top:0;font-size:11px;line-height:16px;color:#555}.cx-st{display:flex;gap:8px;font-size:13px;padding:4px 0;border-bottom:1px dashed #eee}.cx-st span{flex:1;color:#555}.cx-st b.up{color:#e0567a}.cx-st b.dn{color:#999}`);\nX.mini({ id: 'gyxCoax', icon: '🥺', title: '轮到你哄TA', desc: 'TA 低落的时候换你哄', cat: '陪伴', onOpen: () => window.gyxCoaxOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.on = D.on || {}; D.log = D.log || []; D.cfg = Object.assign({ per: 4 }, D.cfg || {}); setInterval(watch, 2500); })();\n\n//# sourceURL=gyx-plugin/轮到你哄TA.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🥺 轮到你哄TA 出错：', e); }
/* ==== 🌧️ 吵架和好 ==== */
try { new Function('X', 'applyMacros', "/* 🌧️ 吵架和好：吵架了可以「挂起」——冷战有计时，TA 会按自己的性格来哄你（或者嘴硬一阵再来）、写道歉信；你也能递一张和好卡；最后来一个「拉钩和好」的小仪式，记进你们的吵架档案（原来只有吵完情绪会延续，这里把和好这件事做出来） */\nif (window.__gyxMakeup) return; window.__gyxMakeup = 1;\nX.feat('gyxMakeup', { n: '🌧️ 吵架和好', desc: '冷战计时、TA 来哄你写道歉信、和好卡、拉钩和好仪式' });\nconst S = X.store('makeup');\nlet D = { on: {}, log: [], cfg: { first: 'auto', minH: 0.5 } };   // on[cid] = {at, why, by:'me'|'ta', steps:[{by, kind, t, at}], tries}; log: 和好过的 {cid, at, end, why, how}\nconst dur = ms => { const m = Math.round(ms / 60000); return m < 60 ? m + ' 分钟' : m < 1440 ? Math.round(m / 60) + ' 小时' : Math.round(m / 1440) + ' 天'; };\nasync function coax(c, f) {\n    const kind = f.tries >= 2 ? 'letter' : 'coax';\n    let t;\n    if (X.bailu()) t = X.cards(kind === 'letter' ? ['道歉', '信', '哄'] : ['哄', '道歉', '聊天'], c, kind === 'letter' ? 3 : 1).join('\\n') || '对不起，是我不好。';\n    else t = X.plain(await X.ask(`${X.who(c)}\\n你们吵架了${f.why ? '（因为：' + f.why + '）' : ''}，已经冷战 ${dur(Date.now() - f.at)}。之前你已经来哄过 ${f.tries} 次${f.steps.length ? '，最近的来回：' + f.steps.slice(-4).map(s => (s.by === 'me' ? '她' : '你') + '：' + s.t).join(' / ') : ''}。\\n最近聊天：\\n${X.recent(c, 10)}\\n\\n${kind === 'letter' ? '写一封道歉信（100~250 字）：真诚说清楚你哪里做得不好、你怎么想的、以后会怎样，按你的性格写，别套话。' : '按你的性格来哄她一次（30~80 字）：可能是认错、撒娇、嘴硬但关心、递台阶……别说教。'}只输出内容。`) || '对不起，是我不好。');\n    f.steps.push({ by: String(c.id), kind, t, at: Date.now() }); f.tries++; await S.set('d', D);\n    X.say(c, kind === 'letter' ? '💌 ' + t : t);\n    if (kind === 'letter') X.notify(c, X.v(`${X.name(c)} 给你写了一封道歉信`, `${X.name(c)} 塞过来一封信`), '去看看', 'gyxMakeupOpen');\n    return { kind, t };\n}\nwindow.gyxMakeupStart = async function (why, cid, by) {\n    const c = X.char(cid) || X.cur(); if (!c) return null; why = why != null ? why : ((document.getElementById('gyxMkWhy') || {}).value || '').trim();\n    D.on[String(c.id)] = { at: Date.now(), why, by: by || 'me', steps: [], tries: 0 }; await S.set('d', D);\n    X.toast(X.v('先冷静一下也好', '记下了，别憋着', '抱抱自己'), X.v('TA 会来找你的', '想和好了随时点「和好」'));\n    window.gyxMakeupOpen(c.id); return D.on[String(c.id)];\n};\nwindow.gyxMakeupCoax = id => { const c = X.char(id) || X.cur(), f = c && D.on[String(c.id)]; return f ? coax(c, f).then(r => { window.gyxMakeupOpen(c.id); return r; }) : null; };\nwindow.gyxMakeupCard = async function (id) {\n    const c = X.char(id) || X.cur(), f = c && D.on[String(c.id)]; if (!f) return; const t = ((document.getElementById('gyxMkCard') || {}).value || '').trim() || X.pick(['我不想跟你吵了', '我们和好吧', '其实我也有不对', '抱一下就不生气了']);\n    f.steps.push({ by: 'me', kind: 'card', t, at: Date.now() }); await S.set('d', D);\n    X.reach(c, `你们在冷战，她递过来一张和好卡：「${t}」。按你的性格回应（接住她的台阶、也说说你的心里话）`); window.gyxMakeupOpen(c.id);\n};\n// 拉钩和好：长按两根小拇指勾在一起\nwindow.gyxMakeupPinky = function (id) {\n    const c = X.char(id) || X.cur(); if (!c || !D.on[String(c.id)]) return;\n    const ov = document.createElement('div'); ov.id = 'gyxMkPk';\n    ov.innerHTML = `<div class=\"mk-pk\"><div class=\"mk-h l\">🤙</div><div class=\"mk-h r\">🤙</div></div><div class=\"mk-t\">${X.v('按住不放，拉钩', '按住，我们拉个钩', '长按 3 秒，和好')}</div><div class=\"mk-bar\"><i></i></div>`;\n    document.body.appendChild(ov);\n    let t0 = 0, raf = 0; const bar = ov.querySelector('.mk-bar i');\n    const step = () => { const p = Math.min(1, (Date.now() - t0) / 3000); bar.style.width = p * 100 + '%'; ov.style.setProperty('--p', p); if (p >= 1) return done(); raf = requestAnimationFrame(step); };\n    const down = e => { e.preventDefault(); t0 = Date.now(); ov.classList.add('hold'); raf = requestAnimationFrame(step); };\n    const up = () => { if (!ov.classList.contains('ok')) { cancelAnimationFrame(raf); ov.classList.remove('hold'); bar.style.width = '0'; } };\n    const done = async () => { ov.classList.add('ok'); ov.querySelector('.mk-t').textContent = X.v('拉钩了，不许再生气', '和好啦', '说好了，以后好好说'); setTimeout(() => ov.remove(), 1800); await window.gyxMakeupEnd(c.id, '拉钩'); };\n    ov.addEventListener('pointerdown', down); ov.addEventListener('pointerup', up); ov.addEventListener('pointerleave', up);\n};\nwindow.gyxMakeupEnd = async function (id, how) {\n    const cid = String(id), f = D.on[cid]; if (!f) return null; delete D.on[cid];\n    const it = { cid, at: f.at, end: Date.now(), why: f.why, how: how || '和好', n: f.steps.length }; D.log.unshift(it); await S.set('d', D);\n    const c = X.char(cid); if (c) X.reach(c, `你们刚刚${how === '拉钩' ? '拉钩' : ''}和好了（冷战了 ${dur(it.end - it.at)}${f.why ? '，因为' + f.why : ''}）。说点和好之后的话，可以撒个娇、说说以后`);\n    if (document.getElementById('gyxMkOv')) window.gyxMakeupOpen(cid); return it;\n};\nwindow.gyxMakeupOpen = function (who) {\n    const c = X.char(who) || X.cur(); if (!c) return; const cid = String(c.id), f = D.on[cid];\n    X.panel('gyxMkOv', f ? '🌧️ 冷战中' : '🌤️ 吵架和好', `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxMakeupOpen')}</div>\n        ${f ? `<div class=\"mk-cold\"><b>${dur(Date.now() - f.at)}</b><span>和 ${X.esc(X.name(c))} 冷战中${f.why ? ' · ' + X.esc(f.why) : ''}</span></div>\n        <div class=\"mk-steps\">${f.steps.map(s => `<div class=\"mk-s ${s.by === 'me' ? 'me' : ''} ${s.kind}\">${s.kind === 'letter' ? '<em>💌 道歉信</em>' : s.kind === 'card' ? '<em>🃏 和好卡</em>' : ''}<p class=\"${s.kind === 'letter' ? 'gyx-hand' : ''}\">${X.esc(s.t).replace(/\\n/g, '<br>')}</p></div>`).join('') || `<div class=\"gyx-tip\">${X.esc(X.name(c))} 还没来哄你……</div>`}</div>\n        <div class=\"gyx-row\"><input id=\"gyxMkCard\" class=\"gyx-in\" style=\"flex:1\" placeholder=\"递一张和好卡（可空，随机一句）\"><button class=\"gyx-btn lite\" onclick=\"gyxMakeupCard('${cid}')\">递过去</button></div>\n        <div class=\"gyx-row\"><button class=\"gyx-btn lite\" onclick=\"this.disabled=true;gyxMakeupCoax('${cid}')\">让 TA 来哄我</button><button class=\"gyx-btn\" onclick=\"gyxMakeupPinky('${cid}')\">🤙 拉钩和好</button><button class=\"gyx-btn lite\" onclick=\"gyxMakeupEnd('${cid}','直接和好')\">直接和好</button></div>`\n        : `<div class=\"gyx-tip\">吵架了就在这里记一下：TA 会知道你们在冷战，按自己的性格来哄你（嘴硬的会嘴硬一阵）。</div><div class=\"gyx-row\"><input id=\"gyxMkWhy\" class=\"gyx-in\" style=\"flex:1\" placeholder=\"因为什么（可空）\"><button class=\"gyx-btn\" onclick=\"gyxMakeupStart(null,'${cid}')\">我们吵架了</button></div>`}\n        <div class=\"gyx-row gyx-tip\">TA 多久来哄一次：冷战超过 <input class=\"gyx-who\" type=\"number\" min=\"0\" step=\"0.5\" value=\"${D.cfg.minH}\" style=\"width:60px\" onchange=\"gyxMakeupCfg(+this.value)\"> 小时（默认模式按这个来，自主模式 TA 自己决定）</div>\n        ${D.log.filter(l => l.cid === cid).length ? '<div class=\"gyx-tip\">吵架档案</div>' + D.log.filter(l => l.cid === cid).slice(0, 20).map(l => `<div class=\"mk-log\"><b>${new Date(l.at).toLocaleDateString()}</b> ${X.esc(l.why || '没说为什么')} · 冷战 ${dur(l.end - l.at)} · ${X.esc(l.how)}</div>`).join('') : ''}`);\n};\nwindow.gyxMakeupCfg = v => { D.cfg.minH = v; S.set('d', D); };\nwindow.gyxMakeupData = () => D;\nasync function tick() {\n    if (!X.on('gyxMakeup')) return;\n    for (const [cid, f] of Object.entries(D.on)) {\n        const c = X.char(cid); if (!c || X.auto(c)) continue;\n        const last = f.steps.length ? f.steps[f.steps.length - 1].at : f.at;\n        if (Date.now() - last >= (+D.cfg.minH || 0) * 3600000 * (1 + f.tries)) await coax(c, f);\n    }\n}\nX.action({ key: 'gyx_makeup', label: '你们在冷战——去哄她 / 写道歉信 / 递台阶', hint: '你们吵架了还没和好', need: c => !!D.on[String(c.id)], run: async c => { const r = await coax(c, D.on[String(c.id)]); return r ? (r.kind === 'letter' ? '写了一封道歉信' : '来哄你了') : null; } }, 'gyxMakeup');\nX.ctx(id => { const f = D.on[String(id)]; if (f) return `【你们在冷战】${dur(Date.now() - f.at)}前吵架了${f.why ? '（因为' + f.why + '）' : ''}，还没和好。你来哄过 ${f.tries} 次。说话要带着这个状态（按你的性格：愧疚、嘴硬、想和好……）。`; const l = D.log.find(x => x.cid === String(id)); return l && Date.now() - l.end < 86400000 ? '【刚和好】你们今天刚和好，说话温柔一点。' : ''; }, 'gyxMakeup');\nX.today(() => ({ title: '🌧️ 吵架和好', rows: Object.entries(D.on).map(([cid, f]) => ({ t: dur(Date.now() - f.at), x: `<b>和 ${X.esc(X.name(X.char(cid)))} 冷战中</b>`, go: `gyxMakeupOpen('${cid}')` })).concat(D.log.filter(l => X.day(new Date(l.end)) === X.day()).map(l => ({ t: '🤙', x: `今天和 ${X.esc(X.name(X.char(l.cid)))} 和好了`, go: `gyxMakeupOpen('${l.cid}')` }))) }), 'gyxMakeup');\nX.widget('gyxMakeupW', { n: '吵架和好', sizes: ['s', 'm'], tap: () => window.gyxMakeupOpen(), r: w => { const E = Object.entries(D.on); if (E.length) return X.gw(w, '🌧️', '冷战中', [dur(Date.now() - E[0][1].at), '和 ' + X.esc(X.name(X.char(E[0][0]))), '点一下去和好']); return X.gw(w, '🌤️', '吵架和好', [D.log.length ? '和好过 ' + D.log.length + ' 次' : '一直好好的', D.log[0] ? '上次 ' + new Date(D.log[0].end).toLocaleDateString() : '']); } }, 'gyxMakeup');\nX.css('gyxMkCss', `.mk-cold{text-align:center;padding:16px;border-radius:20px;background:linear-gradient(160deg,#cfd8e3,#eef2f7);margin:8px 0}.mk-cold b{display:block;font-size:34px;color:#4a5a70}.mk-cold span{font-size:13px;color:#667}\n.mk-steps{display:flex;flex-direction:column;gap:8px;margin:10px 0}.mk-s{max-width:85%;padding:10px 12px;border-radius:16px;background:#f2f2f4;font-size:14px}.mk-s.me{align-self:flex-end;background:#ffe3ec}.mk-s.letter{max-width:100%;background:#fffdf6;border:1px solid #f0e6cc}.mk-s.letter p{font-size:18px;line-height:1.8}.mk-s em{font-style:normal;font-size:12px;color:#999}.mk-s p{margin:2px 0}\n.mk-log{font-size:12.5px;color:#777;padding:4px 0;border-bottom:1px solid #f4f4f4}\n#gyxMkPk{position:fixed;inset:0;z-index:100008;background:rgba(255,240,245,.96);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:20px;user-select:none;touch-action:none}\n.mk-pk{position:relative;width:240px;height:120px}.mk-h{position:absolute;top:20px;font-size:72px;transition:transform .2s}.mk-h.l{left:calc(10px + var(--p,0) * 50px)}.mk-h.r{right:calc(10px + var(--p,0) * 50px);transform:scaleX(-1)}\n.mk-t{font-size:16px;color:#c05}.mk-bar{width:200px;height:6px;border-radius:3px;background:#fde}.mk-bar i{display:block;height:100%;width:0;border-radius:3px;background:#ff5c8a}\n#gyxMkPk.ok .mk-pk{animation:mkB .6s 2}@keyframes mkB{50%{transform:scale(1.15)}}`);\n